<script>export let data; export let form;</script>

<div class="heading"><div><p class="eyebrow">Stay up to date</p><h1>Notifications</h1><p class="muted">Join requests, approvals, and expenses that need your attention.</p></div>{#if data.notifications.some((notification) => !notification.read)}<form method="POST" action="?/markAllRead"><button class="button secondary" type="submit">Mark all as read</button></form>{/if}</div>
{#if form?.error}<p class="error" role="alert">{form.error}</p>{/if}{#if form?.success}<p class="success" role="status">{form.success}</p>{/if}
<section class="card">{#if data.notifications.length}{#each data.notifications as notification}<article class:unread={!notification.read} class="notification"><div><a href={notification.href}><b>{notification.title}</b></a><p>{notification.message}</p><small>{new Date(notification.createdAt).toLocaleString()}</small></div>{#if !notification.read}<form method="POST" action="?/markRead"><input type="hidden" name="notificationId" value={notification.id} /><button class="button secondary" type="submit">Mark read</button></form>{/if}</article>{/each}{:else}<div class="empty"><p>You’re all caught up.</p></div>{/if}</section>

<style>.heading{align-items:end;display:flex;justify-content:space-between;margin:2rem 0}.heading h1{font-size:2.6rem;margin:.7rem 0 .2rem}.eyebrow{color:#d26d35;font-weight:800;text-transform:uppercase}.muted,small{color:#58746b}.success{background:#e6f2ed;border:1px solid #b8deca;border-radius:8px;color:#146c52;padding:.75rem}.notification{align-items:center;border-bottom:1px solid #e6efeb;display:flex;gap:1rem;justify-content:space-between;padding:1rem 0}.notification:last-child{border-bottom:0}.notification.unread{border-left:4px solid #d26d35;padding-left:.75rem}.notification a{text-decoration:none}.notification p{margin:.4rem 0}.notification form{margin:0}.empty{text-align:center;color:#58746b;padding:2rem}@media(max-width:600px){.heading{align-items:flex-start;flex-direction:column;gap:1rem}.notification{align-items:flex-start;flex-direction:column}.notification button{width:100%}}</style>
